    ret = ''
    count = 0
    try:
        for c in original:
            if c.isalpha(): 
                ret+=modified[count]
                count+=1
            else: ret+=c
    except IndexError:
        print('restore_punctuation: strings must have same number of alphabetic chars')
        raise
    return ret

